//! The glyphs for the text of a requested glyph: a single glyph, a ligature
//! (e.g. "ffi" gives U+FB03) or a sequence of glyphs (e.g. a letter followed
//! by combining marks, or a missing ligature). The Unicode normalization
//! forms come from tables (`data/unicode.bin`, generated by the `build_all`
//! tool), limited to the codepoints which can be rendered with the glyph
//! data.

use crate::glyph_data::GlyphData;
use crate::Error;

/// Normalization forms of single codepoints.
pub struct UnicodeTables {
    /// Sorted by codepoint: (codepoint, NFC, NFKC), the forms being single
    /// codepoints (0 when there's none).
    singletons: Vec<(u32, u32, u32)>,
    /// Sorted by codepoint: (codepoint, NFD, NFKD), the forms having several
    /// codepoints (empty when there's none, or when NFKD is NFD).
    decompositions: Vec<(u32, Vec<u32>, Vec<u32>)>,
    /// First NFD codepoints, or u32::MAX for empty NFDs.
    nfd_starts: Vec<u32>,
    /// The ligatures (sorted, with a decomposition): a text with the
    /// compatibility decomposition of one of them is rendered with its glyph.
    ligatures: Vec<u32>,
}

fn varint(bytes: &[u8], pos: &mut usize) -> Result<u32, Error> {
    let mut value: u64 = 0;
    for shift in (0..35).step_by(7) {
        let b = *bytes.get(*pos).ok_or(Error::InvalidData)?;
        *pos += 1;
        value |= ((b & 0x7f) as u64) << shift;
        if b < 0x80 {
            return u32::try_from(value).map_err(|_| Error::InvalidData);
        }
    }
    Err(Error::InvalidData)
}

impl UnicodeTables {
    pub fn new(bytes: &[u8]) -> Result<Self, Error> {
        let mut pos = 0;
        let read_sequence = |pos: &mut usize| -> Result<Vec<u32>, Error> {
            let length = varint(bytes, pos)?;
            (0..length).map(|_| varint(bytes, pos)).collect()
        };
        let count = varint(bytes, &mut pos)?;
        let mut singletons = Vec::with_capacity(count as usize);
        let mut cp = 0;
        for _ in 0..count {
            cp += varint(bytes, &mut pos)?;
            let nfc = varint(bytes, &mut pos)?;
            let nfkc = varint(bytes, &mut pos)?;
            singletons.push((cp, nfc, nfkc));
        }
        let count = varint(bytes, &mut pos)?;
        let mut decompositions = Vec::with_capacity(count as usize);
        let mut cp = 0;
        for _ in 0..count {
            cp += varint(bytes, &mut pos)?;
            let nfd = read_sequence(&mut pos)?;
            let nfkd = read_sequence(&mut pos)?;
            decompositions.push((cp, nfd, nfkd));
        }
        let count = varint(bytes, &mut pos)?;
        let mut ligatures = Vec::with_capacity(count as usize);
        let mut cp = 0;
        for _ in 0..count {
            cp += varint(bytes, &mut pos)?;
            ligatures.push(cp);
        }
        let nfd_starts = decompositions
            .iter()
            .map(|(_, nfd, _)| nfd.first().copied().unwrap_or(u32::MAX))
            .collect();
        Ok(UnicodeTables {
            singletons,
            decompositions,
            nfd_starts,
            ligatures,
        })
    }

    fn singleton(&self, cp: u32) -> Option<(u32, u32)> {
        self.singletons
            .binary_search_by_key(&cp, |&(c, _, _)| c)
            .ok()
            .map(|i| (self.singletons[i].1, self.singletons[i].2))
    }

    fn decomposition(&self, cp: u32) -> Option<(&[u32], &[u32])> {
        self.decompositions
            .binary_search_by_key(&cp, |(c, _, _)| *c)
            .ok()
            .map(|i| (&self.decompositions[i].1[..], &self.decompositions[i].2[..]))
    }
}

/// A glyph: the index of the glyph data (in the sources) and the glyph id.
pub type GlyphRef = (usize, usize);

/// Resolves the texts to glyphs, for some glyph data (the first having a
/// codepoint gives its glyph).
pub struct Resolver<'a> {
    sources: &'a [&'a GlyphData],
    tables: &'a UnicodeTables,
    /// The compatibility forms (NFKC, NFKD) of the codepoints are used too
    /// (e.g. "1" for "①").
    compatibility: bool,
}

impl<'a> Resolver<'a> {
    pub fn new(sources: &'a [&'a GlyphData], tables: &'a UnicodeTables) -> Self {
        Self::with_forms(sources, tables, true)
    }

    /// Use only canonical forms for codepoint fallbacks. Supported ligature
    /// substitutions remain enabled.
    pub fn canonical(sources: &'a [&'a GlyphData], tables: &'a UnicodeTables) -> Self {
        Self::with_forms(sources, tables, false)
    }

    fn with_forms(
        sources: &'a [&'a GlyphData],
        tables: &'a UnicodeTables,
        compatibility: bool,
    ) -> Self {
        Resolver {
            sources,
            tables,
            compatibility,
        }
    }

    /// Prefer the last supported ligature, then the first supported NFD match.
    fn composition(&self, text: &[u32]) -> Option<u32> {
        let tables = self.tables;
        let first = *text.first()?;
        let ligature = tables.ligatures.iter().rev().copied().find(|&cp| {
            tables
                .decomposition(cp)
                .is_some_and(|(nfd, nfkd)| (if nfkd.is_empty() { nfd } else { nfkd }) == text)
                && self.find(cp).is_some()
        });
        ligature.or_else(|| {
            tables
                .nfd_starts
                .iter()
                .zip(&tables.decompositions)
                .find(|&(&start, (cp, nfd, _))| {
                    start == first && nfd[..] == *text && self.find(*cp).is_some()
                })
                .map(|(_, &(cp, _, _))| cp)
        })
    }

    fn find(&self, cp: u32) -> Option<GlyphRef> {
        self.sources
            .iter()
            .enumerate()
            .find_map(|(i, data)| data.glyph_id(cp).map(|gid| (i, gid)))
    }

    /// The glyphs for a single codepoint: itself, its NFC or NFKC form, or
    /// its NFD or NFKD decomposition.
    fn resolve_codepoint(&self, cp: u32, out: &mut Vec<GlyphRef>) -> bool {
        if let Some(glyph) = self.find(cp) {
            out.push(glyph);
            return true;
        }
        if let Some((nfc, nfkc)) = self.tables.singleton(cp) {
            let forms = if self.compatibility {
                &[nfc, nfkc][..]
            } else {
                &[nfc]
            };
            for &form in forms {
                if form != 0 {
                    if let Some(glyph) = self.find(form) {
                        out.push(glyph);
                        return true;
                    }
                }
            }
        }
        if let Some((nfd, nfkd)) = self.tables.decomposition(cp) {
            // A ligature (e.g. "st" for U+FB06 when only U+FB05 is there).
            let nfkc = if nfkd.is_empty() { nfd } else { nfkd };
            if self.compatibility && !nfkc.is_empty() {
                if let Some(glyph) = self.ligature(nfkc) {
                    out.push(glyph);
                    return true;
                }
            }
            let forms = if self.compatibility {
                &[nfd, nfkd][..]
            } else {
                &[nfd]
            };
            for &form in forms {
                if form.len() > 1 {
                    let glyphs: Option<Vec<_>> = form.iter().map(|&c| self.find(c)).collect();
                    if let Some(glyphs) = glyphs {
                        out.extend(glyphs);
                        return true;
                    }
                }
            }
        }
        false
    }

    fn ligature(&self, text: &[u32]) -> Option<GlyphRef> {
        let cp = self.composition(text)?;
        (self.tables.ligatures.binary_search(&cp).is_ok())
            .then(|| self.find(cp))
            .flatten()
    }

    /// The glyphs for a text: a single glyph, a ligature or a composition
    /// (e.g. a letter and a combining mark), or a sequence of glyphs. Empty if
    /// it can't be rendered.
    pub fn resolve(&self, text: &[u32]) -> Vec<GlyphRef> {
        if text.len() > 1 {
            if let Some(glyph) = self.composition(text).and_then(|cp| self.find(cp)) {
                return vec![glyph];
            }
        }
        let mut glyphs = Vec::new();
        for &cp in text {
            if !self.resolve_codepoint(cp, &mut glyphs) {
                return Vec::new();
            }
        }
        glyphs
    }
}
